public class Main {

    // 树状数组，支持单点增加、前缀和查询
    static class Fenwick {
        int n;
        int[] tree;

        Fenwick(int n) {
            this.n = n;
            this.tree = new int[n + 1];
        }

        // 在下标 idx 位置加上 delta
        void add(int idx, int delta) {
            while (idx <= n) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        // 查询前缀和 [1..idx]
        int sum(int idx) {
            int res = 0;
            while (idx > 0) {
                res += tree[idx];
                idx -= idx & -idx;
            }
            return res;
        }

        // 查询区间和 [l..r]
        int rangeSum(int l, int r) {
            return sum(r) - sum(l - 1);
        }
    }

    // 计算单组测试数据答案
    static long solveCase(int n, int[] a) {
        // pos[x] 保存能量值 x 的所有出现位置（下标从1开始）
        ArrayList<Integer>[] pos = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            pos[i] = new ArrayList<>();
        }

        for (int i = 1; i <= n; i++) {
            pos[a[i]].add(i);
        }

        Fenwick bit = new Fenwick(n);
        long ans = 0;

        // 按能量值从小到大处理
        for (int v = 1; v <= n; v++) {
            ArrayList<Integer> arr = pos[v];

            // 先统计当前值 v 的所有同频紧邻对的低值干扰数
            for (int i = 0; i + 1 < arr.size(); i++) {
                int l = arr.get(i);
                int r = arr.get(i + 1);
                ans += bit.rangeSum(l, r);
            }

            // 再将当前值 v 的所有位置加入树状数组
            for (int p : arr) {
                bit.add(p, 1);
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder sb = new StringBuilder();

